typeText:
∀ {α : Type u} [inst : Ord.{u} α]
  {motive :
    {β : α → Type v} → (a : Std.DTreeMap.Internal.Impl.{u, v} α β) → Std.DTreeMap.Internal.Impl.WF.{u, v} a → Prop},
  (∀ {x : α → Type v} {t : Std.DTreeMap.Internal.Impl.{u, v} α x} (a : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t)
      (a_1 : ∀ [Std.TransOrd.{u} α], Std.DTreeMap.Internal.Impl.Ordered.{u, v} t), motive t ⋯) →
    (∀ {x : α → Type v}, motive Std.DTreeMap.Internal.Impl.empty.{u, v} ⋯) →
      (∀ {x : α → Type v} {t : Std.DTreeMap.Internal.Impl.{u, v} α x} {h : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t}
          {k : α} {v : x k} (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t),
          motive t a →
            motive
              (Std.DTreeMap.Internal.Impl.SizedBalancedTree.impl.{u, v}
                (Std.DTreeMap.Internal.Impl.insert.{u, v} k v t h))
              ⋯) →
        (∀ {x : α → Type v} {t : Std.DTreeMap.Internal.Impl.{u, v} α x}
            {h : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t} {k : α} {v : x k}
            (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t),
            motive t a →
              motive
                (Std.DTreeMap.Internal.Impl.SizedBalancedTree.impl.{u, v}
                  (Std.DTreeMap.Internal.Impl.insertIfNew.{u, v} k v t h))
                ⋯) →
          (∀ {x : α → Type v} {t : Std.DTreeMap.Internal.Impl.{u, v} α x}
              {h : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t} {k : α} (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t),
              motive t a →
                motive
                  (Std.DTreeMap.Internal.Impl.SizedBalancedTree.impl.{u, v}
                    (Std.DTreeMap.Internal.Impl.erase.{u, v} k t h))
                  ⋯) →
            (∀ {x : α → Type v} [inst_1 : Std.LawfulEqOrd.{u} α] {t : Std.DTreeMap.Internal.Impl.{u, v} α x}
                {h : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t} {k : α} {f : Option.{v} (x k) → Option.{v} (x k)}
                (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t),
                motive t a →
                  motive
                    (Std.DTreeMap.Internal.Impl.SizedBalancedTree.impl.{u, v}
                      (Std.DTreeMap.Internal.Impl.alter.{u, v} k f t h))
                    ⋯) →
              (∀ {x : Type v} {t : Std.DTreeMap.Internal.Impl.{u, v} α fun x_1 => x}
                  {h : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t} {k : α} {f : Option.{v} x → Option.{v} x}
                  (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t),
                  motive t a →
                    motive
                      (Std.DTreeMap.Internal.Impl.SizedBalancedTree.impl.{u, v}
                        (Std.DTreeMap.Internal.Impl.Const.alter.{u, v} k f t h))
                      ⋯) →
                (∀ {x : α → Type v} [inst_1 : Std.LawfulEqOrd.{u} α] {t : Std.DTreeMap.Internal.Impl.{u, v} α x} {k : α}
                    {f : x k → x k} (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t),
                    motive t a → motive (Std.DTreeMap.Internal.Impl.modify.{u, v} k f t) ⋯) →
                  (∀ {x : Type v} {t : Std.DTreeMap.Internal.Impl.{u, v} α fun x_1 => x} {k : α} {f : x → x}
                      (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t),
                      motive t a → motive (Std.DTreeMap.Internal.Impl.Const.modify.{u, v} k f t) ⋯) →
                    (∀ {x : α → Type v} {t : Std.DTreeMap.Internal.Impl.{u, v} α x}
                        {h : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t} {k : α} {v : x k}
                        (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t),
                        motive t a →
                          motive
                            (Std.DTreeMap.Internal.Impl.SizedBalancedTree.impl.{u, v}
                              (Std.DTreeMap.Internal.Impl.containsThenInsert.{u, v} k v t h).2)
                            ⋯) →
                      (∀ {x : α → Type v} {t : Std.DTreeMap.Internal.Impl.{u, v} α x}
                          {h : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t} {k : α} {v : x k}
                          (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t),
                          motive t a →
                            motive
                              (Std.DTreeMap.Internal.Impl.SizedBalancedTree.impl.{u, v}
                                (Std.DTreeMap.Internal.Impl.containsThenInsertIfNew.{u, v} k v t h).2)
                              ⋯) →
                        (∀ {x : α → Type v} {t : Std.DTreeMap.Internal.Impl.{u, v} α x}
                            {h : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t} {f : (a : α) → x a → Bool}
                            (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t),
                            motive t a →
                              motive
                                (Std.DTreeMap.Internal.Impl.BalancedTree.impl.{u, v}
                                  (Std.DTreeMap.Internal.Impl.filter.{u, v} f t h))
                                ⋯) →
                          (∀ {x : α → Type v} {t₁ t₂ : Std.DTreeMap.Internal.Impl.{u, v} α x}
                              {f : (a : α) → x a → x a → x a} {h : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t₁}
                              [inst_1 : Std.LawfulEqOrd.{u} α] (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t₁),
                              motive t₁ a →
                                motive
                                  (Std.DTreeMap.Internal.Impl.BalancedTree.impl.{u, v}
                                    (Std.DTreeMap.Internal.Impl.mergeWith.{u, v} f t₁ t₂ h))
                                  ⋯) →
                            (∀ {x : Type v} {t₁ t₂ : Std.DTreeMap.Internal.Impl.{u, v} α fun x_1 => x}
                                {f : α → x → x → x} {h : Std.DTreeMap.Internal.Impl.Balanced.{u, v} t₁}
                                (a : Std.DTreeMap.Internal.Impl.WF.{u, v} t₁),
                                motive t₁ a →
                                  motive
                                    (Std.DTreeMap.Internal.Impl.BalancedTree.impl.{u, v}
                                      (Std.DTreeMap.Internal.Impl.Const.mergeWith.{u, v} f t₁ t₂ h))
                                    ⋯) →
                              ∀ {β : α → Type v} {a : Std.DTreeMap.Internal.Impl.{u, v} α β}
                                (t : Std.DTreeMap.Internal.Impl.WF.{u, v} a), motive a t
